<?php require_once __DIR__.'/includes/permissions.php'; require_permission('vaccinations.view');$pdo=db();$u=current_user();$error='';$vaccines=['BCG','Hepatitis B','Pentavalent','Polio','PCV','MMR','Influenza','COVID-19','Other'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=post('action');if($a==='save'&&can('vaccinations.create')){$rid=(int)post('resident_id');$v=trim((string)post('vaccine'));$dose=trim((string)post('dose'));$date=(string)post('administered_date');if(!$rid||!$v||!$date)throw new Exception('Patient, vaccine and date are required.');$q=$pdo->prepare('INSERT INTO vaccinations(resident_id,vaccine,dose,administered_date,administered_by,notes) VALUES(?,?,?,?,?,?)');$q->execute([$rid,$v,$dose,$date,$u['id'],trim((string)post('notes'))]);audit('CREATE','vaccinations',(int)$pdo->lastInsertId(),'Vaccination recorded');flash('success','Vaccination saved.');redirect(BASE_URL.'/vaccinations.php');}if($a==='archive'&&can('vaccinations.delete')){$id=(int)post('id');$pdo->prepare('UPDATE vaccinations SET status="Archived" WHERE id=?')->execute([$id]);audit('ARCHIVE','vaccinations',$id,'Vaccination archived');flash('success','Vaccination archived.');redirect(BASE_URL.'/vaccinations.php');}}catch(Throwable $e){$error=$e->getMessage();}}$search=trim((string)get('search',''));$where=['v.status="Active"'];$params=[];if($search){$where[]='(r.patient_id LIKE ? OR r.first_name LIKE ? OR r.last_name LIKE ? OR v.vaccine LIKE ?)';$x="%$search%";array_push($params,$x,$x,$x,$x);}if($u['role_name']!=='System Administrator'&&$u['role_name']!=='Nurse'&&$u['role_name']!=='Barangay Health Worker'){$where[]='v.administered_by=?';$params[]=$u['id'];}$q=$pdo->prepare('SELECT v.*,r.patient_id,r.first_name,r.last_name,u.full_name administered_name FROM vaccinations v JOIN residents r ON r.id=v.resident_id LEFT JOIN users u ON u.id=v.administered_by WHERE '.implode(' AND ',$where).' ORDER BY v.administered_date DESC,v.id DESC');$q->execute($params);$rows=$q->fetchAll();$residents=$pdo->query('SELECT id,patient_id,first_name,last_name FROM residents WHERE status="Active" ORDER BY last_name,first_name')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Vaccinations</h1><p>Track administered vaccine doses and immunization activity.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><?php if(can('vaccinations.create')):?><div class="panel-head"><h5>Record Vaccination</h5></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="col-md-4"><label>Patient *</label><select name="resident_id" class="form-select" required><option value="">Select</option><?php foreach($residents as $r):?><option value="<?=$r['id']?>"><?=e($r['patient_id'].' — '.$r['last_name'].', '.$r['first_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Vaccine *</label><select name="vaccine" class="form-select" required><?php foreach($vaccines as $v):?><option><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Dose</label><input name="dose" class="form-control" placeholder="1st dose"></div><div class="col-md-3"><label>Date *</label><input type="date" name="administered_date" value="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-8"><label>Notes</label><input name="notes" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Save Vaccination</button></div></form><?php endif;?></div><div class="panel"><div class="panel-head"><h5>Vaccination List</h5><input class="form-control table-search" placeholder="Search..." data-table-search="vaxTable"></div><form class="row g-2 mb-3"><div class="col-md-8"><input name="search" value="<?=e($search)?>" class="form-control" placeholder="Patient ID, name or vaccine"></div><div class="col-md-2"><button class="btn btn-outline-primary w-100">Filter</button></div></form><div class="table-responsive"><table class="table" id="vaxTable"><thead><tr><th>Patient</th><th>Vaccine</th><th>Dose</th><th>Date</th><th>Administered By</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['patient_id'])?> — <?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['vaccine'])?></td><td><?=e($r['dose'])?></td><td><?=e($r['administered_date'])?></td><td><?=e($r['administered_name']??'—')?></td><td><?php if(can('vaccinations.delete')):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary">Archive</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
